import SwiftUI
import AppKit
struct StudioView:View {
 @ObservedObject var store:DiaryStore
 var onOpen:()->Void={}
 @Environment(\.dismiss)private var dismiss
 @State private var studio=StudioData();@State private var message="";@State private var photo:UUID?
 @State private var month=Date();@State private var tags="";@State private var favourite=false;@State private var query="";@State private var only=false;@State private var selected:String?
 @State private var oldPIN="";@State private var newPIN="";@State private var confirmPIN="";@State private var busy=false
 @ObservedObject private var privacy=MacPrivacy.shared
 var key:String{DiaryStore.todayKey(store.date)}
 private func save(){do{try studio.validate();store.commitStudio(studio);message=store.error ?? "저장했어요."}catch{message=error.localizedDescription}}
 private func open(_ date:Date){store.select(date);if store.error==nil{onOpen();dismiss()}}
 var body:some View {VStack(alignment:.leading){HStack{Text("하루 꾸미기").font(.title2);Spacer();Button("닫기"){dismiss()}};if !message.isEmpty{Text(message).font(.caption).foregroundStyle(DesktopPalette.olive)}
  TabView {
   photos.tabItem{Text("1 사진·스티커")}
   room.tabItem{Text("2 상몬의 방")}
   moods.tabItem{Text("3 감정 달력")}
   notes.tabItem{Text("4 태그·즐겨찾기")}
   questions.tabItem{Text("5 오늘의 질문")}
   lock.tabItem{Text("6 일기 잠금")}
  }
 }.padding(20).frame(width:850,height:670).background(DesktopPalette.sidebar).onAppear{studio=store.studio;month=store.date;do{allDays=try store.allDays()}catch{message=error.localizedDescription};let note=studio.note(key);tags=note.Tags.joined(separator:", ");favourite=note.Favourite}.sheet(isPresented:Binding(get:{photo != nil},set:{if !$0{photo=nil}})){if let id=photo,let b=store.entry.blocks.first(where:{$0.id==id}),let data=b.photo{PhotoDecorView(source:data){edited in store.update{e in if let i=e.blocks.firstIndex(where:{$0.id==id}){e.blocks[i].photo=edited}};message=store.error ?? "사진을 적용했어요."}}}
 }
 private var photos:some View {ScrollView{VStack(alignment:.leading,spacing:16){Text("사진을 고른 뒤 자르기·회전·프레임·스티커를 적용해요. 적용 전에는 기존 사진을 바꾸지 않아요.");ForEach(store.entry.blocks.filter{$0.kind == .photo && $0.photo != nil}){b in Button("사진 꾸미기 · "+(b.text.isEmpty ? "사진":String(b.text.prefix(35)))){photo=b.id}};Divider();Text("독립 스티커는 일기 블록으로 추가해 자유롭게 배치할 수 있어요.");HStack{ForEach(0..<4){i in Button(StudioCatalog.stickers[i]+" +"){do{guard store.entry.blocks.count<200 else{throw WindowsCompatibility.fail("한 날짜에는 최대 200개 블록을 넣을 수 있어요.")};let data=try PhotoDecor.encode(PhotoDecor.sticker(i));store.update{e in var b=DiaryBlock(kind:.photo);b.title=StudioCatalog.stickers[i]+" 스티커";b.photo=data;e.blocks.append(b)};message=store.error ?? "일기에 스티커를 추가했어요."}catch{message=error.localizedDescription}}}}}.padding(16)}}
 private var room:some View {VStack(alignment:.leading,spacing:12){Text("가구를 마우스로 움직여요. 최대 24개, 상몬은 모은 옷장 소품을 입고 함께 쉬어요.")
  GeometryReader{geometry in ZStack(alignment:.topLeading){[Color(red:243/255,green:235/255,blue:220/255),Color(red:229/255,green:222/255,blue:239/255),Color(red:224/255,green:233/255,blue:218/255)][studio.RoomTheme];Rectangle().fill(Color(red:214/255,green:197/255,blue:174/255)).frame(height:geometry.size.height/3).offset(y:geometry.size.height*2/3);SharedSangmonView(companion:store.sharedCompanion).frame(width:130,height:130).position(x:geometry.size.width/2,y:geometry.size.height/2)
   ForEach(studio.Furniture){f in let i=StudioCatalog.furnitureKinds.firstIndex(of:f.Kind) ?? 0;VStack{if let image=SangmonImages.image("studio/\(f.Kind).png"){Image(nsImage:image).resizable().scaledToFit().frame(width:58,height:58)};Text(StudioCatalog.furnitureNames[i]).font(.caption)}.padding(12).background(selected==f.Id ? Color(red:245/255,green:212/255,blue:193/255):Color.white,in:RoundedRectangle(cornerRadius:18)).position(x:CGFloat(f.X+50)*geometry.size.width/1000,y:CGFloat(f.Y+50)*geometry.size.height/1000).gesture(DragGesture(coordinateSpace:.named("room")).onChanged{value in selected=f.Id;if let index=studio.Furniture.firstIndex(where:{$0.Id==f.Id}){studio.Furniture[index].X=max(0,min(900,Int(value.location.x*1000/geometry.size.width)-50));studio.Furniture[index].Y=max(0,min(900,Int(value.location.y*1000/geometry.size.height)-50))}}.onEnded{_ in save()})}
  }.coordinateSpace(name:"room").clipShape(RoundedRectangle(cornerRadius:20))}.frame(height:330)
  HStack{ForEach(0..<6){i in Button(StudioCatalog.furnitureNames[i]+" +"){guard studio.Furniture.count<24 else{return};studio.Furniture.append(RoomItem(Kind:StudioCatalog.furnitureKinds[i],X:100+studio.Furniture.count%5*140,Y:300));save()}}}
  HStack{Button("선택 가구 치우기"){studio.Furniture.removeAll{$0.Id==selected};selected=nil;save()}.disabled(selected==nil);Button("배경 바꾸기"){studio.RoomTheme=(studio.RoomTheme+1)%3;save()}}
 }.padding(16)}
 private var moods:some View {ScrollView{VStack(alignment:.leading,spacing:14){Text("직접 선택한 감정만 표시해요. 날짜를 누르면 그날의 일기로 이동해요.");HStack{Button("‹ 이전 달"){shift(-1)};Text(month.formatted(.dateTime.year().month()));Button("다음 달 ›"){shift(1)}};let calendar=Calendar(identifier:.gregorian);let components=calendar.dateComponents([.year,.month],from:month);let first=calendar.date(from:components)!;let count=calendar.range(of:.day,in:.month,for:first)!.count;let offset=calendar.component(.weekday,from:first)-1
  LazyVGrid(columns:Array(repeating:GridItem(.flexible()),count:7),spacing:8){ForEach(["일","월","화","수","목","금","토"],id:\.self){Text($0)};ForEach(0..<offset,id:\.self){_ in Color.clear.frame(height:36)};ForEach(1...count,id:\.self){day in let date=calendar.date(byAdding:.day,value:day-1,to:first)!;let mood=allDays[DiaryStore.todayKey(date)]?.mood;let index=StudioCatalog.moods.firstIndex(of:mood ?? "");Button{open(date)}label:{VStack{Text("\(day)");Text(mood ?? "").font(.caption2)}.frame(maxWidth:.infinity,minHeight:54).background(index.map{[Color(red:223/255,green:232/255,blue:213/255),Color(red:250/255,green:228/255,blue:164/255),Color(red:223/255,green:216/255,blue:236/255),Color(red:213/255,green:224/255,blue:237/255),Color(red:244/255,green:216/255,blue:221/255)][$0]} ?? Color.clear,in:RoundedRectangle(cornerRadius:10))}.buttonStyle(.plain)}}
 }.padding(16)}}
 @State private var allDays:[String:DiaryEntry]=[:]
 private func shift(_ delta:Int){let c=Calendar(identifier:.gregorian);if let date=c.date(byAdding:.month,value:delta,to:month),(1...9999).contains(c.component(.year,from:date)){month=date}}
 private var notes:some View {VStack(alignment:.leading,spacing:12){Text(key+" · 태그는 쉼표로 구분해요. 최대 10개·각 20자예요.");TextField("태그",text:$tags);Toggle("이날을 즐겨찾기",isOn:$favourite);Button("이날의 분류 저장"){do{var seen=Set<String>();let values=tags.split(separator:",").map{$0.trimmingCharacters(in:.whitespacesAndNewlines).trimmingCharacters(in:CharacterSet(charactersIn:"#"))}.filter{!$0.isEmpty&&seen.insert($0.lowercased()).inserted};try studio.setNote(StudioNote(Date:key,Tags:values,Favourite:favourite));save()}catch{message=error.localizedDescription}};Divider();TextField("태그로 찾기",text:$query);Toggle("즐겨찾기만",isOn:$only);ScrollView{LazyVStack(alignment:.leading){ForEach(Array(studio.Pages.filter{(!only||$0.Favourite)&&(query.isEmpty||$0.Tags.contains{$0.localizedCaseInsensitiveContains(query.trimmingCharacters(in:CharacterSet(charactersIn:"#")))})}.sorted{$0.Date>$1.Date}.prefix(100))){n in Button((n.Favourite ? "★ ":"")+n.Date+"  "+n.Tags.map{"#"+$0}.joined(separator:" ")){let f=DateFormatter();f.calendar=Calendar(identifier:.gregorian);f.locale=Locale(identifier:"en_US_POSIX");f.dateFormat="yyyy-MM-dd";if let date=f.date(from:n.Date){open(date)}}}}}.frame(maxHeight:.infinity)}.padding(16)}
 private var questions:some View {VStack(alignment:.leading,spacing:20){Text(key+"의 작은 질문");let question=StudioData.question(store.date);Text(question).font(.title2);Button("이 질문으로 일기 쓰기"){guard !store.entry.blocks.contains(where:{$0.prompt==question})else{message="이미 이 질문이 일기에 있어요.";return};guard store.entry.blocks.count<200 else{message="블록이 가득 찼어요.";return};store.update{e in var b=DiaryBlock(kind:.text);b.title="오늘의 질문";b.prompt=question;e.blocks.append(b)};if store.error==nil{onOpen();dismiss()}};Text("날짜별 질문은 기기 안의 공통 목록에서 골라요. 답변을 외부로 보내지 않아요.");Spacer()}.padding(20)}
 private var lock:some View {VStack(alignment:.leading,spacing:14){Text("이 기기의 화면 잠금").font(.title2);Text("앱을 열 때와 5분 동안 조작하지 않았을 때 잠가요. PIN은 백업에 넣지 않아요. 화면을 가리는 기능이며 저장 파일 자체를 암호화하지 않아요. PIN을 잊지 않도록 보관해 주세요.");Text(privacy.enabled ? "현재 켜짐":"현재 꺼짐");SecureField("현재 PIN (처음에는 비워 두세요)",text:$oldPIN);SecureField("새 PIN · 숫자 6~12자리",text:$newPIN);SecureField("새 PIN 확인",text:$confirmPIN);HStack{Button("PIN 설정·변경"){updatePIN(false)};Button("잠금 끄기"){updatePIN(true)}.disabled(!privacy.enabled);Button("지금 잠그기"){dismiss();privacy.locked=true}.disabled(!privacy.enabled)}.disabled(busy);Spacer()}.padding(20)}
 private func updatePIN(_ disable:Bool){let old=oldPIN,pin=newPIN,confirm=confirmPIN,vault=privacy.vault;busy=true;Task{do{try await Task.detached{if disable{try vault.disable(old)}else{guard pin==confirm else{throw WindowsCompatibility.fail("두 PIN 입력이 달라요.")};try vault.set(old:old,pin:pin)}}.value;try privacy.refresh();oldPIN="";newPIN="";confirmPIN="";message="잠금 설정을 저장했어요."}catch{message=error.localizedDescription};busy=false}}
}
